package com.edgecloud.alert.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import java.math.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.test.util.ReflectionTestUtils; import com.edgecloud.alert.entity.*; import com.edgecloud.alert.evaluation.*; import com.edgecloud.alert.repository.*;
class AlertSuppressionServiceTest {private MaintenanceWindowRepository windows=mock(MaintenanceWindowRepository.class);private AlertSuppressionHistoryRepository history=mock(AlertSuppressionHistoryRepository.class);private AlertSuppressionService service=new AlertSuppressionService(windows,history);private UUID project=UUID.randomUUID();private Instant at=Instant.parse("2026-08-11T10:00:00Z");
 @Test void recordsEveryOverlappingMatchingWindowOnce(){var first=window(MaintenanceScopeType.PROJECT,null,null);var second=window(MaintenanceScopeType.DEVICE,null,"device-1");when(windows.findActive(project,at)).thenReturn(List.of(first,second));assertThat(service.suppressMatching(result(project,"device-1",at))).isEqualTo(2);verify(history,times(2)).save(any());}
 @Test void rejectsWrongScopeProjectExpiredAndDuplicate(){var device=window(MaintenanceScopeType.DEVICE,null,"other");when(windows.findActive(project,at)).thenReturn(List.of(device));assertThat(service.suppressMatching(result(project,"device-1",at))).isZero();when(windows.findActive(project,at)).thenReturn(List.of());assertThat(service.suppressMatching(result(project,"device-1",at))).isZero();var active=window(MaintenanceScopeType.PROJECT,null,null);when(windows.findActive(project,at)).thenReturn(List.of(active));when(history.existsByMaintenanceWindowIdAndDedupKey(eq(active.getId()),any())).thenReturn(true);assertThat(service.suppressMatching(result(project,"device-1",at))).isZero();verify(history,never()).save(any());}
 private MaintenanceWindow window(MaintenanceScopeType scope,UUID serviceId,String device){var w=new MaintenanceWindow(project,scope,serviceId,device,"Window","Reason",at.minusSeconds(10),at.plusSeconds(10),true,UUID.randomUUID());ReflectionTestUtils.setField(w,"id",UUID.randomUUID());return w;}
 private AlertEvaluationResult result(UUID p,String source,Instant evaluated){return new AlertEvaluationResult(UUID.randomUUID(),"CPU",p,AlertEvaluationSourceType.DEVICE,source,AlertRuleMetricType.CPU_USAGE,BigDecimal.TEN,BigDecimal.ONE,AlertRuleComparisonOperator.GREATER_THAN,Severity.HIGH,true,evaluated);}
}
